/**
 * Which set of pages the menu shows. The eight old pages stay in the build and
 * reachable by URL either way.
 */
async function applyProductionFlag() {
    pgEnsureSide();
    pgRenderSide();
    if (window.feShowPhase) window.feShowPhase();
}

// ── In-betweens between two key shots ────────────────────────────────────
/*
 * Connect 1A to 1B (drag 1A's image port onto 1B, or "In-betweens to the next
 * shot" on 1A), say how many frames and how often, and direct them: each frame
 * on its own, and stretches of time on their lanes. Everything that spends goes
 * through the one confirmation, reading the route's own free plan first.
 */
const IB = { setup: null, span: null, sel: 0, rangeEdit: null, price: null };

// ── Side panel: outline + palette ─────────────────────────────────────────

function pgRenderSide() {
    const host = document.getElementById('pgSidePanel');
    if (!host) return;
    const on = state.currentProject;
    host.style.display = on ? '' : 'none';
    host.dataset.flagHidden = on ? '' : '1';
    if (!on) return;
    // The outline needs the graph even before the page is opened.
    if (!PG.graph || PG.graph.project_id !== state.currentProject.id) {
        if (!PG.loadingSide) { PG.loadingSide = true; loadProductionGraph().finally(() => { PG.loadingSide = false; }); }
        return;
    }
    const find = (PG.find || '').toLowerCase();
    const scenes = [];
    for (const s of pgShots()) {
        if (find && !String(s.shot_code).toLowerCase().includes(find)) continue;
        let sc = scenes.find(x => x.id === s.scene_id);
        if (!sc) scenes.push(sc = { id: s.scene_id, label: s.scene_label, shots: [] });
        sc.shots.push(s);
    }
    const onGraph = s => pgVisible(s);
    const list = document.getElementById('pgOutline');
    if (list) list.innerHTML = scenes.map(sc => `<div class="pg-side-scene"><span>${esc(sc.label)}</span><span>${sc.shots.length}</span></div>`
        + sc.shots.map(s => {
            const seq = s.sequence_id ? pgNode('seq:' + s.sequence_id) : null;
            const card = pgCollapsedOf(s.key);
            const note = card ? `in ${card.label} (collapsed)` : !onGraph(s) ? 'off graph' : seq ? seq.name : '';
            return `<div class="pg-side-row${PG.sel === s.key ? ' on' : ''}" draggable="true"
                ondragstart="event.dataTransfer.setData('text/pg-add','${s.key}')" onclick="pgSideClick('${s.key}')">
                <i style="background:${s.frames.length ? '#4fd39c' : '#f08a8a'}"></i><span>${esc(s.shot_code)}</span><span class="note">${esc(note)}</span></div>`;
        }).join('')).join('') || '<div class="pg-note">No shots yet.</div>';
}

// After every DOMContentLoaded listener, so the chrome has built the panel the
// outline and palette go into.
document.addEventListener('DOMContentLoaded', () => setTimeout(applyProductionFlag, 0));

